/* Boot: the compliance notice and the service-worker update flow.

   This used to be an inline script block in tail.html, which forced
   script-src 'unsafe-inline' in the Content-Security-Policy — and
   'unsafe-inline' is most of what a CSP is for. It is a real file now, so the
   split build ships script-src 'self' with no escape hatch at all. The
   single-file build inlines it again and pins it by sha256 hash instead.
*/

/* ══════════════════════════════════════════════════════════════════
   Error reporting  ·  board item 81

   This project's defining failure was a dead app that looked identical to a
   working one for a full day. The reason nobody knew is that nothing reported.
   A member whose app throws on boot does not file a ticket — they delete it.

   Four rules, all of them about not making things worse:

     1. Never throw from the reporter. A member seeing an error about the error
        reporter is worse than a member seeing nothing.
     2. Send at most a handful per session. A render loop that throws every
        frame must not turn one bug into a denial-of-service against your own
        backend, paid for by the member's battery.
     3. Deduplicate in the browser. The same error twice is the same error.
     4. Send nothing identifying. No user id, no email, no hash — the app puts
        church and prayer ids in the hash. The server scrubs again, but the
        first responsibility is not to send it.
   ══════════════════════════════════════════════════════════════════ */
(function(){
  var MAX_PER_SESSION = 5, sent = 0, seen = {};

  function report(message, stack){
    try {
      if (sent >= MAX_PER_SESSION) return;
      message = String(message || "").slice(0, 500);
      if (!message) return;
      var key = message + "|" + String(stack || "").slice(0, 120);
      if (seen[key]) return;
      seen[key] = 1;
      sent++;

      var api = (typeof FLOURISH_API === "string" && FLOURISH_API) ||
                (window.FLOURISH_CONFIG && window.FLOURISH_CONFIG.apiUrl) || "";
      if (!api) return;

      var payload = JSON.stringify({
        message:  message,
        stack:    String(stack || "").slice(0, 4000),
        build_id: (typeof APP_VERSION === "string" ? APP_VERSION : ""),
        // pathname only. location.hash carries church and prayer ids.
        page:     location.pathname.slice(0, 120),
        platform: (window.Capacitor && window.Capacitor.isNativePlatform &&
                   window.Capacitor.isNativePlatform()) ? "ios" : "web"
      });

      // sendBeacon survives the page being closed, which is exactly when a boot
      // crash gets reported — the member is already killing the app.
      if (navigator.sendBeacon) {
        navigator.sendBeacon(api + "/api/client-error",
          new Blob([payload], { type: "application/json" }));
      } else {
        fetch(api + "/api/client-error", {
          method: "POST", headers: { "Content-Type": "application/json" },
          body: payload, keepalive: true
        }).catch(function(){});
      }
    } catch (e) { /* rule 1 */ }
  }

  window.addEventListener("error", function(e){
    report(e && e.message, e && e.error && e.error.stack);
  });
  window.addEventListener("unhandledrejection", function(e){
    var r = e && e.reason;
    report(r && (r.message || String(r)), r && r.stack);
  });

  // Exposed so a catch block can report deliberately, and so the tests can.
  window.flourishReportError = report;
})();

function flourishDismissNotice(){
  try{ localStorage.setItem("flourish_notice","1"); }catch(e){}
  var b=document.getElementById("flourish-compliance-bar"); if(b) b.hidden=true;
}
(function(){
  var seen=false; try{ seen=!!localStorage.getItem("flourish_notice"); }catch(e){}
  var b=document.getElementById("flourish-compliance-bar");
  if(b && !seen) setTimeout(function(){ b.hidden=false; }, 1400);
})();
/* Board item 47 — an open tab must not silently run stale code, and a new
   version must not swap in under someone mid-lesson.

   The worker no longer calls skipWaiting() on its own. It installs, then
   WAITS. We notice the waiting worker and ask. If they say yes we tell it to
   activate and reload once, on controllerchange. If they say no, nothing
   changes until they next open the app — which is the honest behaviour when
   someone is halfway through writing a prayer request. */
if("serviceWorker" in navigator && location.protocol.startsWith("http")){
  navigator.serviceWorker.register("sw.js").then(function(reg){
    // Reload ONLY after the user accepted an update. controllerchange also
    // fires on the very first install, when the freshly activated worker calls
    // clients.claim() — reloading there would bounce every first-time visitor
    // for no reason. (Caught by tools/test_offline.js, which navigated out from
    // under its own evaluate.)
    var accepted = false, reloading = false;
    navigator.serviceWorker.addEventListener("controllerchange", function(){
      if(!accepted || reloading) return; reloading = true; location.reload();
    });

    function offer(worker){
      if(!worker) return;
      // A worker waiting with no current controller is the FIRST install, not
      // an update. Prompting there would ask someone to reload a page they
      // just opened, for a version they are already running.
      if(!navigator.serviceWorker.controller) return;
      function accept(){ accepted = true; worker.postMessage({ type: "SKIP_WAITING" }); }
      if(typeof window.showUpdatePrompt === "function") window.showUpdatePrompt(worker, accept);
      else accept();
    }

    if(reg.waiting) offer(reg.waiting);
    reg.addEventListener("updatefound", function(){
      var w = reg.installing;
      if(!w) return;
      w.addEventListener("statechange", function(){ if(w.state === "installed") offer(w); });
    });

    // Check for a new deploy when the app is brought back to the foreground.
    document.addEventListener("visibilitychange", function(){
      if(document.visibilityState === "visible") reg.update().catch(function(){});
    });
  }).catch(function(){});
}

/* ── HAPTICS ──────────────────────────────────────────────────────────────
   The cheapest thing that separates a native-feeling app from a web page.
   Three call sites only, so it stays meaningful: a tap, a success, a refusal.
   A buzz on everything is worse than no buzz at all — it stops carrying
   information and starts being noise a person turns off in Settings.

   Native path is the Capacitor bridge, which registers Haptics on
   window.Capacitor.Plugins at runtime; @capacitor/haptics is in package.json
   so `npx cap sync ios` installs the pod. No import, because this bundle has
   no module loader. Web falls back to navigator.vibrate, which Safari ignores
   — correctly: there is no vibration API on iOS Safari, only in the shell.

   Off switch: localStorage flourish.haptics = "off". Someone will want it. */
(function(){
  var OFF = false;
  try { OFF = localStorage.getItem("flourish.haptics") === "off"; } catch(e){}

  function plugin(){
    return (window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.Haptics) || null;
  }

  function haptic(kind){
    if (OFF) return;
    var H = plugin();
    try {
      if (H) {
        if (kind === "success" || kind === "warning" || kind === "error") {
          H.notification({ type: kind.toUpperCase() });
        } else if (kind === "heavy") {
          H.impact({ style: "HEAVY" });
        } else if (kind === "medium") {
          H.impact({ style: "MEDIUM" });
        } else {
          H.impact({ style: "LIGHT" });
        }
        return;
      }
      if (navigator.vibrate) {
        navigator.vibrate(kind === "success" ? [12, 40, 22]
                        : kind === "error"   ? [26, 50, 26]
                        : kind === "heavy"   ? 22
                        : kind === "medium"  ? 14 : 8);
      }
    } catch(e){ /* a phone that will not buzz is not a failure worth reporting */ }
  }

  window.flourishHaptic = haptic;
  window.flourishHapticsEnabled = function(on){
    OFF = !on;
    try { localStorage.setItem("flourish.haptics", on ? "on" : "off"); } catch(e){}
  };

  /* One delegated listener for the tap tick. Pointerdown, not click: the
     buzz has to land with the finger, not after the handler returns, or it
     reads as lag rather than feedback. */
  document.addEventListener("pointerdown", function(ev){
    var t = ev.target;
    if (!t || !t.closest) return;
    var el = t.closest("button,.btn,.nav-btn,.card,.chip,.iconbtn,[data-act]");
    if (!el) return;
    if (el.disabled || el.getAttribute("aria-disabled") === "true") return;
    if (el.classList && el.classList.contains("is-loading")) return;
    haptic(el.classList && el.classList.contains("nav-btn") ? "light" : "medium");
  }, { passive: true });
})();
